1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked   = "未检查"
18		StatusPass        = "通过"
19		StatusDefect      = "发现缺陷"
20		StatusToolMissing = "工具缺失"
21		StatusTimeout     = "超时"
22	)
23	
24	// ReportArtifact identifies the audited artifact by name and content hash.
25	type ReportArtifact struct {
26		Name string `json:"name"`
27		Hash string `json:"hash"`
28	}
29	
30	// ReportRule is one rule together with the invariant check result. The note
31	// carries the original checker description: counterexample evidence for a
32	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
33	// or an optional remark for a passing check. It is empty for reports built
34	// only from invariant booleans.
35	type ReportRule struct {
36		ID          string `json:"id"`
37		Kind        string `json:"kind"`
38		Severity    string `json:"severity"`
39		Invariant   string `json:"invariant"`
40		RequiresABI bool   `json:"requiresABI"`
41		Version     string `json:"version"`
42		Status      string `json:"status"`
43		Note        string `json:"note,omitempty"`
44	}
45	
46	// ReportFinding binds a defect to its artifact, rule, version and evidence.
47	type ReportFinding struct {
48		ArtifactHash string `json:"artifactHash"`
49		RuleID       string `json:"ruleId"`
50		Version      string `json:"version"`
51		Severity     string `json:"severity"`
52		Invariant    string `json:"invariant"`
53		Evidence     string `json:"evidence"`
54	}
55	
56	// Report is the persisted audit result.
57	type Report struct {
58		ReportID string          `json:"reportId"`
59		Artifact ReportArtifact  `json:"artifact"`
60		Rules    []ReportRule    `json:"rules"`
61		Findings []ReportFinding `json:"findings"`
62	}
63	
64	// wireArtifact is the JSON shape of an artifact in an audit submission.
65	type wireArtifact struct {
66		Name     string `json:"name"`
67		ABI      string `json:"abi"`
68		Bytecode string `json:"bytecode"`
69		Source   string `json:"source"`
70	}
71	
72	// wireRule is the JSON shape of a rule in an audit submission.
73	type wireRule struct {
74		ID          string `json:"id"`
75		Kind        string `json:"kind"`
76		Severity    string `json:"severity"`
77		Invariant   string `json:"invariant"`
78		RequiresABI bool   `json:"requiresABI"`
79		Version     string `json:"version"`
80	}
81	
82	// CheckRecord is one imported per-rule check result: the artifact hash and
83	// rule version it was produced against, the conclusion status, and the
84	// original checker note (counterexample, tool or deadline remark).
85	type CheckRecord struct {
86		ArtifactHash string
87		RuleID       string
88		Version      string
89		Status       string
90		Note         string
91	}
92	
93	// wireCheck is the JSON shape of one entry in the checks array.
94	type wireCheck struct {
95		ArtifactHash string `json:"artifactHash"`
96		RuleID       string `json:"ruleId"`
97		Version      string `json:"version"`
98		Status       string `json:"status"`
99		Note         string `json:"note"`
100	}
101	
102	// wireInput is the JSON object accepted by the audit command.
103	type wireInput struct {
104		Artifact   wireArtifact               `json:"artifact"`
105		Rules      []wireRule                 `json:"rules"`
106		Invariants map[string]json.RawMessage `json:"invariants"`
107		Checks     []wireCheck                `json:"checks"`
108	}
109	
110	// Fixed submission field spellings. A submission is decoded through these
111	// exact names only, mirroring strictReportJSON on the read side:
112	// encoding/json otherwise falls back to case-insensitive field matching, so
113	// an extension member such as "StAtus" would silently decode into the status
114	// field and could override — or launder — the conclusion carried by the
115	// formal "status" member, depending on where the extension member appears.
116	// Case variants, whitespace-padded names and unknown members are extension
117	// data and never reach the decoder. The invariants object is not rewritten:
118	// invariant names are user-defined rather than fixed fields, so "Inv" and
119	// "inv" stay two independent invariants and a padded name is not trimmed.
120	var (
121		submissionTopKeys   = []string{"artifact", "rules", "invariants", "checks"}
122		artifactWireKeys    = []string{"name", "abi", "bytecode", "source"}
123		submissionRuleKeys  = []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}
124		submissionCheckKeys = []string{"artifactHash", "ruleId", "version", "status", "note"}
125	)
126	
127	// strictSubmissionJSON rewrites submission bytes to the fixed fields under
128	// their agreed spelling, at the top level and inside the artifact, every rule
129	// and every check record. Member order and extension members no longer
130	// influence the decoded values: a case variant or whitespace-padded name can
131	// neither override a formal value nor substitute for a missing or invalid
132	// one. Names are compared after JSON string decoding, so a fixed name written
133	// with escapes still denotes that field. The invariants object passes through
134	// untouched because its member names are user-defined.
135	func strictSubmissionJSON(data []byte) ([]byte, error) {
136		var obj map[string]json.RawMessage
137		if err := json.Unmarshal(data, &obj); err != nil {
138			return nil, err
139		}
140		out := make(map[string]json.RawMessage, len(submissionTopKeys))
141		for _, k := range submissionTopKeys {
142			if v, ok := obj[k]; ok {
143				out[k] = v
144			}
145		}
146		if raw, ok := out["artifact"]; ok && string(raw) != "null" {
147			f, err := fixedFieldsOnly(raw, artifactWireKeys)
148			if err != nil {
149				return nil, err
150			}
151			out["artifact"] = f
152		}
153		if raw, ok := out["rules"]; ok && string(raw) != "null" {
154			f, err := fixedFieldsInArray(raw, submissionRuleKeys)
155			if err != nil {
156				return nil, err
157			}
158			out["rules"] = f
159		}
160		if raw, ok := out["checks"]; ok && string(raw) != "null" {
161			f, err := fixedFieldsInArray(raw, submissionCheckKeys)
162			if err != nil {
163				return nil, err
164			}
165			out["checks"] = f
166		}
167		return json.Marshal(out)
168	}
169	
170	// validateFormalCheckStatuses checks the formal "status" member of every
171	// strict check record. The strict rewrite dropped extension members, so the
172	// status seen here is the agreed-spelling one alone: a missing formal status,
173	// a non-string one, or an unsupported value rejects the whole submission
174	// even when an adjacent "StAtus" extension member carried a legal-looking
175	// value. The error names the rule the record is for so the offending entry is
176	// identifiable.
177	func validateFormalCheckStatuses(strict []byte) error {
178		var top struct {
179			Checks []map[string]json.RawMessage `json:"checks"`
180		}
181		if err := json.Unmarshal(strict, &top); err != nil {
182			return errInvalid("invalid JSON: " + err.Error())
183		}
184		for _, rec := range top.Checks {
185			where := "check record"
186			if raw, ok := rec["ruleId"]; ok {
187				var ruleID string
188				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
189					where = "check for rule " + ruleID
190				}
191			}
192			raw, ok := rec["status"]
193			if !ok {
194				return errInvalid(where + ": status is required")
195			}
196			var status string
197			if err := json.Unmarshal(raw, &status); err != nil {
198				return errInvalid(where + ": status must be a string")
199			}
200			if !validCheckStatus(status) {
201				return errInvalid(where + ": unknown status " + status)
202			}
203		}
204		return nil
205	}
206	
207	// ParseAuditInput decodes an audit submission JSON object into domain values.
208	// Invariant values must be JSON booleans; any other type is an error. Any JSON
209	// object in the submission that repeats a member name rejects the whole
210	// submission: the decoder keeps only the last value silently, so a repeated
211	// invariant key would choose a conclusion by member order instead of giving
212	// one trustworthy result. Only the fixed fields under their agreed spelling
213	// participate: case variants and whitespace-padded names are extension data
214	// and are ignored, so they can neither override a formal value nor supply one
215	// when the formal member is missing or unsupported. Invariant names are not
216	// fixed fields — they are user-defined, compared case sensitively and never
217	// trimmed.
218	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
219		if dup := findDuplicateJSONMember(data); dup != nil {
220			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
221		}
222		strict, err := strictSubmissionJSON(data)
223		if err != nil {
224			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
225		}
226		if err := validateFormalCheckStatuses(strict); err != nil {
227			return Artifact{}, nil, nil, nil, err
228		}
229		var in wireInput
230		if err := json.Unmarshal(strict, &in); err != nil {
231			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
232		}
233		invariants := make(map[string]bool, len(in.Invariants))
234		for key, raw := range in.Invariants {
235			// Only JSON true/false is a conclusion. Unmarshalling directly into a
236			// bool would turn null into the zero value false, which would falsely
237			// record a defect; require the token to be a boolean instead.
238			var token any
239			if err := json.Unmarshal(raw, &token); err != nil {
240				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
241			}
242			holds, ok := token.(bool)
243			if !ok {
244				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
245			}
246			invariants[key] = holds
247		}
248		artifact := Artifact{
249			Name:     in.Artifact.Name,
250			ABI:      in.Artifact.ABI,
251			Bytecode: in.Artifact.Bytecode,
252			Source:   in.Artifact.Source,
253		}
254		rules := make([]Rule, 0, len(in.Rules))
255		for _, wr := range in.Rules {
256			rules = append(rules, Rule{
257				ID:          wr.ID,
258				Kind:        wr.Kind,
259				Severity:    wr.Severity,
260				Invariant:   wr.Invariant,
261				RequiresABI: wr.RequiresABI,
262				Version:     wr.Version,
263			})
264		}
265		checks := make([]CheckRecord, 0, len(in.Checks))
266		for _, wc := range in.Checks {
267			checks = append(checks, CheckRecord{
268				ArtifactHash: wc.ArtifactHash,
269				RuleID:       wc.RuleID,
270				Version:      wc.Version,
271				Status:       wc.Status,
272				Note:         wc.Note,
273			})
274		}
275		return artifact, rules, invariants, checks, nil
276	}
277	
278	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
279	// bytecode and source strings contribute; field boundaries are explicit
280	// (length-prefixed) so that different splits never collide. The source is
281	// hashed as a field value, never read from disk, and the name does not
282	// participate.
283	func ArtifactHash(a Artifact) string {
284		h := sha256.New()
285		h.Write([]byte("contractsentinel-artifact-v1\n"))
286		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
287			fmt.Fprintf(h, "%d\n", len(field))
288			h.Write([]byte(field))
289		}
290		sum := h.Sum(nil)
291		return hex.EncodeToString(sum)
292	}
293	
294	// validCheckStatus reports whether status is one of the four recorded check
295	// conclusions.
296	func validCheckStatus(status string) bool {
297		switch status {
298		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
299			return true
300		}
301		return false
302	}
303	
304	// BuildReport evaluates rules against the artifact and invariant values and
305	// imported check records and produces the report to persist. Insufficient
306	// inputs (missing ABI for a rule that requires it, missing bytecode for a
307	// symbolic rule) fail the whole submission and are never recorded as defects.
308	// Imported checks are validated as a whole: unknown rules, duplicate records,
309	// unknown statuses, missing notes, hash or version mismatches, and a rule
310	// receiving both a check record and an invariant boolean all reject the
311	// submission without producing a report.
312	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
313		if artifact.Name == "" {
314			return Report{}, errInvalid("artifact name is required")
315		}
316		hash := ArtifactHash(artifact)
317		seen := make(map[string]bool, len(rules))
318		ruleByID := make(map[string]Rule, len(rules))
319		for _, rule := range rules {
320			if rule.ID == "" {
321				return Report{}, errInvalid("rule id is required")
322			}
323			if rule.Version == "" {
324				return Report{}, errInvalid("rule " + rule.ID + " version is required")
325			}
326			if seen[rule.ID] {
327				return Report{}, errInvalid("duplicate rule id " + rule.ID)
328			}
329			seen[rule.ID] = true
330			ruleByID[rule.ID] = rule
331			if rule.RequiresABI && artifact.ABI == "" {
332				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
333			}
334			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
335				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
336			}
337		}
338		checkByRule := make(map[string]CheckRecord, len(checks))
339		for _, check := range checks {
340			if check.RuleID == "" {
341				return Report{}, errInvalid("check rule id is required")
342			}
343			rule, ok := ruleByID[check.RuleID]
344			if !ok {
345				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
346			}
347			if _, dup := checkByRule[check.RuleID]; dup {
348				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
349			}
350			if check.ArtifactHash != hash {
351				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
352			}
353			if check.Version != rule.Version {
354				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
355			}
356			if !validCheckStatus(check.Status) {
357				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
358			}
359			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
360				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
361			}
362			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
363				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
364			}
365			checkByRule[check.RuleID] = check
366		}
367		report := Report{
368			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
369			Rules:    []ReportRule{},
370			Findings: []ReportFinding{},
371		}
372		for _, rule := range rules {
373			status := StatusUnchecked
374			note := ""
375			if check, ok := checkByRule[rule.ID]; ok {
376				status = check.Status
377				note = check.Note
378			} else if holds, checked := invariants[rule.Invariant]; checked {
379				if holds {
380					status = StatusPass
381				} else {
382					status = StatusDefect
383				}
384			}
385			report.Rules = append(report.Rules, ReportRule{
386				ID:          rule.ID,
387				Kind:        rule.Kind,
388				Severity:    rule.Severity,
389				Invariant:   rule.Invariant,
390				RequiresABI: rule.RequiresABI,
391				Version:     rule.Version,
392				Status:      status,
393				Note:        note,
394			})
395			if status == StatusDefect {
396				evidence := note
397				if evidence == "" {
398					evidence = "invariant " + rule.Invariant + " does not hold"
399				}
400				report.Findings = append(report.Findings, ReportFinding{
401					ArtifactHash: hash,
402					RuleID:       rule.ID,
403					Version:      rule.Version,
404					Severity:     rule.Severity,
405					Invariant:    rule.Invariant,
406					Evidence:     evidence,
407				})
408			}
409		}
410		report.ReportID = ReportID(report)
411		return report, nil
412	}
413	
414	// canonicalRule is the order-independent view of a rule used for the id. The
415	// note is omitted when empty so reports built only from invariant booleans
416	// keep their original ids.
417	type canonicalRule struct {
418		ID          string `json:"id"`
419		Kind        string `json:"kind"`
420		Severity    string `json:"severity"`
421		Invariant   string `json:"invariant"`
422		RequiresABI bool   `json:"requiresABI"`
423		Version     string `json:"version"`
424		Status      string `json:"status"`
425		Note        string `json:"note,omitempty"`
426	}
427	
428	// canonicalFinding is the order-independent view of a finding used for the id.
429	type canonicalFinding struct {
430		ArtifactHash string `json:"artifactHash"`
431		RuleID       string `json:"ruleId"`
432		Version      string `json:"version"`
433		Severity     string `json:"severity"`
434		Invariant    string `json:"invariant"`
435		Evidence     string `json:"evidence"`
436	}
437	
438	// canonicalReport is the deterministic content a report id is computed from.
439	type canonicalReport struct {
440		ArtifactHash string             `json:"artifactHash"`
441		Name         string             `json:"name"`
442		Rules        []canonicalRule    `json:"rules"`
443		Findings     []canonicalFinding `json:"findings"`
444	}
445	
446	// canonicalize renders a report into its order-independent form.
447	func canonicalize(report Report) canonicalReport {
448		cr := canonicalReport{
449			ArtifactHash: report.Artifact.Hash,
450			Name:         report.Artifact.Name,
451		}
452		for _, rule := range report.Rules {
453			cr.Rules = append(cr.Rules, canonicalRule{
454				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
455				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
456				Version: rule.Version, Status: rule.Status, Note: rule.Note,
457			})
458		}
459		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
460		for _, finding := range report.Findings {
461			cr.Findings = append(cr.Findings, canonicalFinding{
462				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
463				Version: finding.Version, Severity: finding.Severity,
464				Invariant: finding.Invariant, Evidence: finding.Evidence,
465			})
466		}
467		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
468		return cr
469	}
470	
471	// ReportID returns the content-addressed identifier of a report. The id binds
472	// the artifact hash, name, complete rule definitions, the invariant value
473	// used by each rule (unchecked and explicit pass are distinct), and the
474	// findings. Rule order, invariant key order and unrelated invariant keys do
475	// not influence it.
476	func ReportID(r Report) string {
477		data, err := json.Marshal(canonicalize(r))
478		if err != nil {
479			panic(err) // canonical values are all strings and bools
480		}
481		sum := sha256.Sum256(data)
482		return hex.EncodeToString(sum[:])
483	}
484	
485	// validateReport checks every archive legality condition against r. It is the
486	// single definition of a legal report: the id and artifact hash are 64
487	// lowercase hex characters, the id matches the content, the artifact name is
488	// present, rule ids are present and unique with non-empty versions, statuses
489	// use the five recorded values, tool-missing and timeout notes are
490	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
491	// artifact hash, version, severity, invariant and evidence match the rule.
492	// The same conditions apply to submissions and to stored archives: a
493	// recomputed id never makes an invalid report legal. fail is errInvalid for
494	// submissions and errCorrupt for stored archives.
495	func validateReport(r Report, fail func(string) error) error {
496		if !validReportID(r.ReportID) {
497			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
498		}
499		if r.Artifact.Name == "" {
500			return fail("report " + r.ReportID + " artifact name is required")
501		}
502		if !validReportID(r.Artifact.Hash) {
503			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
504		}
505		if ReportID(r) != r.ReportID {
506			return fail("report content does not match id " + r.ReportID)
507		}
508		seenRule := make(map[string]bool, len(r.Rules))
509		defectByID := make(map[string]ReportRule)
510		for _, rule := range r.Rules {
511			if rule.ID == "" {
512				return fail("report " + r.ReportID + " has a rule with an empty id")
513			}
514			if seenRule[rule.ID] {
515				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
516			}
517			seenRule[rule.ID] = true
518			if rule.Version == "" {
519				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
520			}
521			switch rule.Status {
522			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
523			default:
524				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
525			}
526			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
527				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
528			}
529			if rule.Status == StatusDefect {
530				defectByID[rule.ID] = rule
531			}
532		}
533		seenFinding := make(map[string]bool, len(r.Findings))
534		for _, f := range r.Findings {
535			if f.RuleID == "" {
536				return fail("report " + r.ReportID + " has a finding with an empty rule id")
537			}
538			rule, ok := defectByID[f.RuleID]
539			if !ok {
540				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
541			}
542			if seenFinding[f.RuleID] {
543				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
544			}
545			seenFinding[f.RuleID] = true
546			if f.ArtifactHash != r.Artifact.Hash {
547				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
548			}
549			if f.Version != rule.Version {
550				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
551			}
552			if f.Severity != rule.Severity {
553				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
554			}
555			if f.Invariant != rule.Invariant {
556				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
557			}
558			wantEvidence := rule.Note
559			if wantEvidence == "" {
560				wantEvidence = "invariant " + rule.Invariant + " does not hold"
561			}
562			if f.Evidence != wantEvidence {
563				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
564			}
565		}
566		for id := range defectByID {
567			if !seenFinding[id] {
568				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
569			}
570		}
571		return nil
572	}
573	
574	// validStoredReport validates archive contents.
575	func validStoredReport(r Report) error {
576		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
577	}
578	
579	// validSubmittedReport validates a submission before any store operation.
580	func validSubmittedReport(r Report) error {
581		return validateReport(r, func(msg string) error { return errInvalid(msg) })
582	}
583	
584	// duplicateArchiveError classifies an archive that repeats a JSON member as
585	// corrupt and names the requested report id, the decoded member name and the
586	// object carrying it (with array position and rule id when applicable).
587	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
588		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
589	}
590	
591	// Fixed report fields by their original spelling. A stored archive must be
592	// decoded through these exact names only: encoding/json otherwise falls back
593	// to case-insensitive field matching, so an extension member such as "StAtus"
594	// would silently decode into the status field and could override — or launder
595	// — the conclusion recorded by the original "status" member, depending on
596	// where the extension member happens to appear. The trusted content of a
597	// report is carried by the fixed fields alone; case variants, whitespace-
598	// padded names and unknown members are extension data and never reach the
599	// decoder.
600	var (
601		reportTopKeys = []string{"reportId", "artifact", "rules", "findings"}
602		artifactKeys  = []string{"name", "hash"}
603		ruleKeys      = []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}
604		findingKeys   = []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
605	)
606	
607	// fixedFieldsOnly rewrites one JSON object keeping only the named members.
608	// Names are compared after JSON string decoding, so a member name written
609	// with escapes still denotes its fixed field. Exact duplicates were already
610	// rejected by findDuplicateJSONMember, so each kept name appears at most
611	// once.
612	func fixedFieldsOnly(raw json.RawMessage, keys []string) (json.RawMessage, error) {
613		var obj map[string]json.RawMessage
614		if err := json.Unmarshal(raw, &obj); err != nil {
615			return nil, err
616		}
617		out := make(map[string]json.RawMessage, len(keys))
618		for _, k := range keys {
619			if v, ok := obj[k]; ok {
620				out[k] = v
621			}
622		}
623		return json.Marshal(out)
624	}
625	
626	// fixedFieldsInArray rewrites every element of a JSON array with
627	// fixedFieldsOnly. A null array stays null so the decoded slice keeps the
628	// same nil-ness as before.
629	func fixedFieldsInArray(raw json.RawMessage, keys []string) (json.RawMessage, error) {
630		var elems []json.RawMessage
631		if err := json.Unmarshal(raw, &elems); err != nil {
632			return nil, err
633		}
634		if elems == nil {
635			return raw, nil
636		}
637		out := make([]json.RawMessage, 0, len(elems))
638		for _, e := range elems {
639			f, err := fixedFieldsOnly(e, keys)
640			if err != nil {
641				return nil, err
642			}
643			out = append(out, f)
644		}
645		return json.Marshal(out)
646	}
647	
648	// strictReportJSON rewrites archive bytes to the fixed report fields under
649	// their original spelling, at the top level and inside the artifact, every
650	// rule and every finding. Member order and extension members no longer
651	// influence the decoded report.
652	func strictReportJSON(data []byte) ([]byte, error) {
653		var obj map[string]json.RawMessage
654		if err := json.Unmarshal(data, &obj); err != nil {
655			return nil, err
656		}
657		out := make(map[string]json.RawMessage, len(reportTopKeys))
658		for _, k := range reportTopKeys {
659			if v, ok := obj[k]; ok {
660				out[k] = v
661			}
662		}
663		if raw, ok := out["artifact"]; ok {
664			f, err := fixedFieldsOnly(raw, artifactKeys)
665			if err != nil {
666				return nil, err
667			}
668			out["artifact"] = f
669		}
670		for _, arrayKey := range []struct {
671			name string
672			keys []string
673		}{
674			{"rules", ruleKeys},
675			{"findings", findingKeys},
676		} {
677			if raw, ok := out[arrayKey.name]; ok {
678				f, err := fixedFieldsInArray(raw, arrayKey.keys)
679				if err != nil {
680					return nil, err
681				}
682				out[arrayKey.name] = f
683			}
684		}
685		return json.Marshal(out)
686	}
687	
688	// loadStoredReport parses archive bytes for id and fully validates them.
689	func loadStoredReport(data []byte, id string) (Report, error) {
690		// Read-side counterpart of the submission check: json.Unmarshal silently
691		// keeps the last value for a repeated member, so an archive that writes a
692		// rule status as 发现缺陷 and then 通过 would decode to whichever came
693		// last. The recomputed id and the rule/finding correspondence all operate
694		// on that last-wins value and could therefore pass, accepting an archive
695		// with two conflicting conclusions. Any repeated member in any object
696		// makes the archive corrupt, regardless of the last value.
697		if dup := findDuplicateJSONMember(data); dup != nil {
698			return Report{}, duplicateArchiveError(id, data, dup)
699		}
700		strict, err := strictReportJSON(data)
701		if err != nil {
702			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
703		}
704		var r Report
705		if err := json.Unmarshal(strict, &r); err != nil {
706			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
707		}
708		if r.ReportID != id {
709			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
710		}
711		if err := validStoredReport(r); err != nil {
712			return Report{}, err
713		}
714		return r, nil
715	}
716	
717	// saveReportHook, when set, is invoked after the archive existence check and
718	// before the atomic publish. It lets tests simulate another process racing to
719	// claim the same report id.
720	var saveReportHook func(finalPath string)
721	
722	// SaveReport persists a report under the store directory. The store is safe
723	// for concurrent writers: identical reports share one file and all
724	// submissions succeed, different reports never overwrite each other, and
725	// readers only ever observe complete files. A submission is fully validated
726	// before any store operation, so an invalid report creates no store and no
727	// files. A pre-existing file with the same id must be a valid archive of the
728	// same report; a corrupted archive makes the submission fail while keeping the
729	// original file, even when the corruption appears only during the save. The
730	// first successfully archived bytes are never replaced by later submissions.
731	func SaveReport(dir string, r Report) error {
732		if err := validSubmittedReport(r); err != nil {
733			return err
734		}
735		if err := os.MkdirAll(dir, 0o755); err != nil {
736			return err
737		}
738		finalPath := filepath.Join(dir, r.ReportID+".json")
739		if existing, err := os.ReadFile(finalPath); err == nil {
740			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
741				return err
742			}
743			return nil
744		} else if !os.IsNotExist(err) {
745			return err
746		}
747		data, err := json.Marshal(r)
748		if err != nil {
749			return err
750		}
751		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
752		if err != nil {
753			return err
754		}
755		tmpPath := tmp.Name()
756		cleanup := func() { os.Remove(tmpPath) }
757		if _, err := tmp.Write(data); err != nil {
758			tmp.Close()
759			cleanup()
760			return err
761		}
762		if err := tmp.Sync(); err != nil {
763			tmp.Close()
764			cleanup()
765			return err
766		}
767		if err := tmp.Close(); err != nil {
768			cleanup()
769			return err
770		}
771		if saveReportHook != nil {
772			saveReportHook(finalPath)
773		}
774		if err := os.Link(tmpPath, finalPath); err != nil {
775			cleanup()
776			if os.IsExist(err) {
777				existing, readErr := os.ReadFile(finalPath)
778				if readErr != nil {
779					return readErr
780				}
781				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
782					return err
783				}
784				return nil
785			}
786			return err
787		}
788		cleanup()
789		return nil
790	}
791	
792	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
793	// hex characters; missing, corrupted or tampered archives produce a clear
794	// error. The store is only read, never created or modified.
795	func LoadReport(dir, id string) (Report, error) {
796		if !validReportID(id) {
797			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
798		}
799		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
800		if err != nil {
801			if os.IsNotExist(err) {
802				return Report{}, errNotFound("report " + id + " not found")
803			}
804			return Report{}, err
805		}
806		return loadStoredReport(data, id)
807	}
808	
809	type errNotFound string
810	
811	func (e errNotFound) Error() string { return string(e) }
812	
813	type errCorrupt string
814	
815	func (e errCorrupt) Error() string { return string(e) }
816

